"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["61914"],{88213(e){e.exports=JSON.parse('{"id":"FIN-837","slug":"card-network","term":"Card Network","also_known_as":[],"difficulty":"Intermediate","definition":"A card network is a company that operates the system connecting card issuers, merchants and their banks, setting the rules and processing the information that allows card payments to be authorised, cleared and settled.","explanation":["When you pay by card, the card network routes the transaction between the merchant\'s bank and your card issuer, checks that the payment is approved and enables the money to move between banks.","The largest global card networks are Visa and Mastercard, which do not issue cards themselves but provide the network that banks use. Other networks, such as American Express and Discover, often both run the network and issue cards directly to customers. Some countries have national networks, such as UnionPay in China, RuPay in India and others.","For example, a bank in one country issues a Visa debit card to a customer. When that customer pays at a restaurant abroad, the Visa network connects the restaurant\'s bank with the customer\'s bank so that the payment can be approved within seconds.","Card networks earn fees on transactions, set interchange fee levels within limits set by regulators, and establish security standards, such as chip and contactless technology. Their scale and importance have made them the focus of competition and regulatory scrutiny in several countries."],"note":"","total":1500,"prev":{"slug":"carbon-credit","term":"Carbon Credit"},"next":{"slug":"carried-interest","term":"Carried Interest"}}')}}]);